cat > /app/hierarchical_model.stan <<'EOF'
// Hierarchical Bayesian model:
//   y_i  ~ Binomial(n_i, theta_i)
//   theta_i ~ Beta(alpha, beta)
//   p(alpha, beta)  prop  (alpha + beta)^(-5/2)   (improper prior)
data {
  int<lower=1> N;              // number of groups/observations
  array[N] int<lower=0> y;     // successes in each group
  array[N] int<lower=1> n;     // number of trials in each group
}
parameters {
  real<lower=0> alpha;         // beta hyper-parameter (concentration)
  real<lower=0> beta;          // beta hyper-parameter (concentration)
  array[N] real<lower=0, upper=1> theta;  // group-level success probabilities
}
model {
  // Improper prior: (alpha, beta) proportional to (alpha + beta)^(-5/2)
  target += -2.5 * log(alpha + beta);

  // Hyper-prior on group probabilities
  theta ~ beta(alpha, beta);

  // Likelihood
  for (i in 1:N) {
    y[i] ~ binomial(n[i], theta[i]);
  }
}
EOF
echo '--- stan file ---'; cat /app/hierarchical_model.stan

